// n8n Code Node — Normaliser 01
const item = $input.first().json;
const headers = item.headers || {};
const body = item.body || {};
const email = (body.email || '').toLowerCase().trim();

let domain = null;
if (email.includes('@')) {
  domain = email.split('@')[1].toLowerCase();
}

const publicDomains = [
  'gmail.com','yahoo.com','hotmail.com','outlook.com',
  'live.com','msn.com','rediffmail.com','icloud.com',
  'aol.com','protonmail.com','yandex.com'
];

const isBusinessEmail = !!(domain && !publicDomains.includes(domain));

return [{
  json: {
    name: (body.name || '').trim() || null,
    email,
    email_domain: domain,
    is_business_email: isBusinessEmail,
    linkedin: body.linkedin || null,
    message: body.message || null,
    source: body.source || null,
    referred_by: body.referred_by || null,
    ip_address: headers['x-forwarded-for'] || headers['x-real-ip'] || null,
    user_agent: headers['user-agent'] || null,
    received_at: new Date().toISOString()
  }
}];

// FIX BUG 1: Switch_Source-1 removed — it was routing all 4 sources to the same
// Decoder node anyway, adding latency with no benefit.
// Normaliser-01 now connects directly here.

const item = $input.first().json;

const sourceMap = {
  '4wf5673': 'website_form',
  '4ld5673': 'linkedin',
  '4cer5673': 'cold_email_reply',
  '4rfr5673': 'referral'
};

const output = { ...item };
if (sourceMap[item.source]) {
  output.source = sourceMap[item.source];
}

return [{ json: output }];

// Sanitize public domain lead before inserting to Postgres
const item = $input.first().json;

function s(val) {
  if (val === null || val === undefined) return '';
  return String(val).replace(/\0/g, '').replace(/'/g, "''").trim();
}
function safeInt(val, def = 0) {
  const n = parseInt(val); return isNaN(n) ? def : n;
}

// Deterministic ID
const base = `${item.email}|${item.source||''}|${item.ip_address||''}`;
let hash = 0;
for (let i = 0; i < base.length; i++) {
  hash = (hash << 5) - hash + base.charCodeAt(i);
  hash |= 0;
}

return [{ json: {
  id:           Math.abs(hash),
  name:         s(item.name),
  email:        s(item.email).toLowerCase(),
  email_domain: s(item.email_domain),
  linkedin:     s(item.linkedin),
  message:      s(item.message),
  source:       s(item.source),
  referred_by:  s(item.referred_by),
  ip_address:   s(item.ip_address),
  received_at:  item.received_at || new Date().toISOString()
}}];

// Create a deterministic integer ID from email + source + ip
const item = $input.first().json;

const base = `${item.email}|${item.source}|${item.ip_address}`;
let hash = 0;
for (let i = 0; i < base.length; i++) {
  hash = (hash << 5) - hash + base.charCodeAt(i);
  hash |= 0;
}

return [{
  json: {
    id: Math.abs(hash),
    name: item.name,
    email: item.email,
    email_domain: item.email_domain,
    is_business_email: item.is_business_email,
    linkedin: item.linkedin,
    message: item.message,
    source: item.source,
    referred_by: item.referred_by,
    ip_address: item.ip_address,
    user_agent: item.user_agent,
    received_at: item.received_at
  }
}];

// FIX BUG 3 & 4: Sanitize all inputs before they reach SQL queries.
// - Escapes single quotes to prevent SQL injection
// - Coerces numeric/boolean fields to safe defaults
// - Removes null bytes
const item = $input.first().json;

function s(val) {
  if (val === null || val === undefined) return '';
  return String(val).replace(/\0/g, '').replace(/'/g, "''");
}

function safeInt(val, def = 0) {
  const n = parseInt(val);
  return isNaN(n) ? def : n;
}

function safeBool(val, def = false) {
  if (typeof val === 'boolean') return val;
  if (val === 'true' || val === '1') return true;
  if (val === 'false' || val === '0') return false;
  return def;
}

return [{
  json: {
    id: safeInt(item.id),
    name: s(item.name),
    email: s(item.email),
    email_domain: s(item.email_domain),
    linkedin: s(item.linkedin),
    message: s(item.message),
    source: s(item.source),
    referred_by: s(item.referred_by),
    ip_address: s(item.ip_address),
    user_agent: s(item.user_agent),
    received_at: item.received_at,
    is_business_email: item.is_business_email
  }
}];

const lead = $input.first().json;
