const companyDB = {
  'lntecc.com': { company: 'L&T Technology Services', industry: 'Engineering Services', company_size: 20000 },
  'zoho.com': { company: 'Zoho Corporation', industry: 'Software', company_size: 12000 }
};

let companyData = companyDB[domain];
