// Merge lead (from Split In Batches) + template (from Fetch_Template_DB)
const tpl  = $input.first().json;
const lead = $('Split In Batches').item.json;

// If no template found in DB, skip this lead gracefully
if (!tpl || !tpl.subject || !tpl.html) {
  return [{ json: { ...lead, sendEmail: 0, sequence_active: false, next_email_scheduled: null } }];
}

function fill(str) {
  return (str || '')
    .replace(/\{\{name\}\}/g,    lead.name    || '')
    .replace(/\{\{company\}\}/g, lead.company || '')
    .replace(/\{\{email\}\}/g,   lead.email   || '')
    .replace(/\{\{id\}\}/g,      String(lead.id || ''))
    .replace(/\{\{segment\}\}/g, lead.segment || '');
}

const baseUrl    = 'https://automation.theworkflowengineer.ovh/webhook';
const trackBase  = `${baseUrl}/f759437e-95f1-46c3-8c98-7cc6395181a8`;
const pixelUrl   = `${baseUrl}/f759437e-95f1-46c3-8c98-7cc6395181a9?cid=${lead.id}&source=4eo5674`;
const pixel      = `<img src="${pixelUrl}" width="1" height="1" alt="">`;

let html    = fill(tpl.html);
let subject = fill(tpl.subject);

// Append pixel only if not already present
if (!html.includes('4eo5674')) html += pixel;

const stage     = lead.email_sequence_stage || 1;
const nextStage = stage + 1;
const nextScheduled = nextStage <= 4
  ? new Date(Date.now() + 5 * 60 * 1000).toISOString()
  : null;

return [{ json: {
  ...lead,
  subject,
  html,
  sendEmail:             stage,
  next_email_scheduled:  nextScheduled,
  sequence_active:       nextStage <= 4
}}];

// Convert nested templates object → flat array of rows for upsert
const body = $input.first().json.body || $input.first().json;
const templates = body.templates || body;
const rows = [];
for (const segment of Object.keys(templates)) {
  const stages = templates[segment];
  for (const stage of Object.keys(stages)) {
    const t = stages[stage];
    if (!t || !t.subject || !t.html) continue;
    rows.push({ json: {
      segment,
      stage: parseInt(stage),
      subject: String(t.subject).replace(/'/g, "''"),
      html:    String(t.html).replace(/'/g, "''")
    }});
  }
}
return rows.length ? rows : [{ json: { error: 'no valid templates' } }];

// Normalize, sanitize, enrich each uploaded lead
const body  = $input.first().json.body || $input.first().json;
const leads = body.leads || (Array.isArray(body) ? body : [body]);

const publicDomains = new Set([
  'gmail.com','yahoo.com','hotmail.com','outlook.com','live.com',
  'msn.com','rediffmail.com','icloud.com','aol.com','protonmail.com','yandex.com'
]);

const companyDB = {
  'lntecc.com': { company: 'L&T Technology Services', industry: 'Engineering Services', company_size: 20000 },
  'zoho.com':   { company: 'Zoho Corporation',         industry: 'Software',             company_size: 12000 }
};

function s(val) {
  if (val == null) return '';
  return String(val).replace(/\0/g, '').replace(/'/g, "''").trim();
}
function safeInt(val, def=0) { const n=parseInt(val); return isNaN(n)?def:n; }

const sourceMap = { website_form:'website_form', linkedin:'linkedin',
  cold_email_reply:'cold_email_reply', referral:'referral',
  '4wf5673':'website_form','4ld5673':'linkedin',
  '4cer5673':'cold_email_reply','4rfr5673':'referral' };

const output = [];
const now = new Date().toISOString();

for (const raw of leads) {
  const email = s(raw.email).toLowerCase();
  if (!email || !email.includes('@')) continue;

  const domain = email.split('@')[1].toLowerCase();
  const isBusinessEmail = !publicDomains.has(domain);
  if (!isBusinessEmail) continue; // skip public domain leads

  let cd = companyDB[domain];
  if (!cd) {
    const size = Math.floor(Math.random()*40)+5;
    cd = { company: domain.split('.')[0], industry: 'Technology', company_size: size };
  }
  const segment = cd.company_size > 50 ? 'Enterprise'
                : cd.company_size >= 10 ? 'Mid-Market' : 'SMB';

  // deterministic ID
  const base = `${email}|${s(raw.source)||'manual'}|upload`;
  let hash = 0;
  for (let i=0;i<base.length;i++) { hash = (hash<<5)-hash+base.charCodeAt(i); hash|=0; }
  const id = Math.abs(hash);

  output.push({ json: {
    id,
    name:         s(raw.name),
    email,
    domain,
    company:      s(raw.company) || cd.company,
    company_size: cd.company_size,
    industry:     cd.industry,
    segment,
    linkedin:     s(raw.linkedin),
    message:      s(raw.message),
    source:       sourceMap[s(raw.source)] || 'manual_upload',
    referred_by:  s(raw.referred_by),
    ip_address:   '',
    lead_score:   0,
    status:       'New',
    created_at:   now
  }});
}

return output.length ? output : [{ json: { _skip: true, count: 0 } }];

